    private int[] recoverTransactions(Connection target, Connection source, RecoveryMaps maps) throws SQLException {
        int recovered = 0;
        int skipped = 0;
        String selectSql = """
                SELECT id, account_id, category_id, project_id, person_id,
                       %s AS project_activity_id,
                       %s AS related_transaction_id,
                       transaction_type,
                       %s AS transaction_purpose,
                       %s AS transaction_status,
                       amount, transaction_date, description,
                       %s AS source,
                       %s AS payment_method,
                       %s AS reference_number,
                       %s AS created_at
                FROM transactions
                WHERE %s = 0
                ORDER BY date(transaction_date), id
                """.formatted(
                recoveryColumnExpression(source, "transactions", "project_activity_id", "NULL"),
                recoveryColumnExpression(source, "transactions", "related_transaction_id", "NULL"),
                recoveryColumnExpression(source, "transactions", "transaction_purpose", "'NORMAL'"),
                recoveryColumnExpression(source, "transactions", "transaction_status", "'COMPLETED'"),
                recoveryColumnExpression(source, "transactions", "source", "'RECOVERED'"),
                recoveryColumnExpression(source, "transactions", "payment_method", "NULL"),
                recoveryColumnExpression(source, "transactions", "reference_number", "NULL"),
                recoveryColumnExpression(source, "transactions", "created_at", "CURRENT_TIMESTAMP"),
                recoveryColumnExpression(source, "transactions", "is_deleted", "0")
        );
        try (Statement select = source.createStatement();
             ResultSet rows = select.executeQuery(selectSql)) {
            while (rows.next()) {
                Integer accountId = maps.accounts().get(rows.getInt("account_id"));
                if (accountId == null) {
                    skipped++;
                    continue;
                }
                Integer categoryId = nullableSourceMappedId(rows, "category_id", maps.categories());
                Integer projectId = nullableSourceMappedId(rows, "project_id", maps.projects());
                Integer personId = nullableSourceMappedId(rows, "person_id", maps.people());
                String transactionDate = safeText(rows.getString("transaction_date"), "");
                RecoveredTransactionLedgerValues ledgerValues = recoveredTransactionLedgerValues(rows);
                if (transactionDate.isBlank() || transactionDuplicateExists(target, accountId, rows, categoryId, projectId, personId, ledgerValues)) {
                    skipped++;
                    continue;
                }
                insertRecoveredTransaction(target, rows, accountId, categoryId, projectId, personId, ledgerValues);
                recovered++;
            }
        }
        return new int[]{recovered, skipped};
    }

    private String recoveryColumnExpression(Connection connection, String tableName, String columnName, String fallback) throws SQLException {
        return columnExists(connection, tableName, columnName) ? columnName : fallback;
    }

    private RecoveredTransactionLedgerValues recoveredTransactionLedgerValues(ResultSet row) throws SQLException {
        String transactionType = normalizedToken(rowsText(row, "transaction_type", "EXPENSE"), "EXPENSE");
        String transactionPurpose = normalizedToken(rowsText(row, "transaction_purpose", PURPOSE_NORMAL), PURPOSE_NORMAL);
        String transactionStatus = normalizedRecoveredTransactionStatus(rowsText(row, "transaction_status", "COMPLETED"));
        if (Set.of(PURPOSE_MONEY_LENT, PURPOSE_MONEY_BORROWED, PURPOSE_LENT_REPAID, PURPOSE_BORROWED_REPAID).contains(transactionPurpose)
                && Set.of("INCOME", "EXPENSE").contains(transactionType)) {
            transactionType = "LOAN";
        }
        requireRecoveredLedgerToken(LEDGER_TRANSACTION_TYPES, transactionType, "type", row.getInt("id"));
        requireRecoveredLedgerToken(LEDGER_TRANSACTION_PURPOSES, transactionPurpose, "purpose", row.getInt("id"));
        requireRecoveredLedgerToken(LEDGER_TRANSACTION_STATUSES, transactionStatus, "status", row.getInt("id"));
        return new RecoveredTransactionLedgerValues(transactionType, transactionPurpose, transactionStatus);
    }

    private String normalizedRecoveredTransactionStatus(String status) {
        String normalized = normalizedToken(status, "COMPLETED");
        return switch (normalized) {
            case "POSTED", "PAID" -> "COMPLETED";
            default -> normalized;
        };
    }

    private void requireRecoveredLedgerToken(List<String> allowed, String value, String fieldName, int sourceTransactionId) {
        if (!allowed.contains(value)) {
            throw new IllegalArgumentException("Unsupported transaction " + fieldName + " '" + value
                    + "' in recovered database transaction #" + sourceTransactionId
                    + ". Run PFMIS database initialization on the source database or remove unsupported records before recovery.");
        }
    }

    private Integer nullableSourceMappedId(ResultSet rows, String columnName, java.util.Map<Integer, Integer> map) throws SQLException {
        int sourceId = rows.getInt(columnName);
        return rows.wasNull() || sourceId <= 0 ? null : map.get(sourceId);
    }

    private boolean transactionDuplicateExists(Connection connection, Integer accountId, ResultSet row,
                                               Integer categoryId, Integer projectId, Integer personId,
                                               RecoveredTransactionLedgerValues ledgerValues) throws SQLException {
        try (PreparedStatement statement = connection.prepareStatement("""
                SELECT 1
                FROM transactions
                WHERE account_id = ?
                  AND COALESCE(category_id, 0) = COALESCE(?, 0)
                  AND COALESCE(project_id, 0) = COALESCE(?, 0)
                  AND COALESCE(person_id, 0) = COALESCE(?, 0)
                  AND transaction_type = ?
                  AND transaction_purpose = ?
                  AND transaction_status = ?
                  AND ABS(amount - ?) < 0.005
                  AND transaction_date = ?
                  AND COALESCE(reference_number, '') = COALESCE(?, '')
                  AND COALESCE(description, '') = COALESCE(?, '')
                LIMIT 1
                """)) {
            statement.setInt(1, accountId);
            setNullableInt(statement, 2, categoryId);
            setNullableInt(statement, 3, projectId);
            setNullableInt(statement, 4, personId);
            statement.setString(5, ledgerValues.transactionType());
            statement.setString(6, ledgerValues.transactionPurpose());
            statement.setString(7, ledgerValues.transactionStatus());
            statement.setDouble(8, row.getDouble("amount"));
            statement.setString(9, row.getString("transaction_date"));
            statement.setString(10, cleanNullable(row.getString("reference_number")));
            statement.setString(11, safeText(row.getString("description"), ""));
            try (ResultSet resultSet = statement.executeQuery()) {
                return resultSet.next();
            }
        }
    }

    private void insertRecoveredTransaction(Connection connection, ResultSet row, Integer accountId,
                                            Integer categoryId, Integer projectId, Integer personId,
                                            RecoveredTransactionLedgerValues ledgerValues) throws SQLException {
        boolean idAvailable = !transactionIdExists(connection, row.getInt("id"));
        String sql = idAvailable
                ? """
                INSERT INTO transactions (
                    id, account_id, category_id, project_id, person_id, project_activity_id,
                    related_transaction_id, transaction_type, transaction_purpose, transaction_status,
                    amount, transaction_date, description, source, payment_method, reference_number, created_at
                ) VALUES (?, ?, ?, ?, ?, NULL, NULL, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """
                : """
                INSERT INTO transactions (
                    account_id, category_id, project_id, person_id, project_activity_id,
                    related_transaction_id, transaction_type, transaction_purpose, transaction_status,
                    amount, transaction_date, description, source, payment_method, reference_number, created_at
                ) VALUES (?, ?, ?, ?, NULL, NULL, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """;
        try (PreparedStatement statement = connection.prepareStatement(sql)) {
            int index = 1;
            if (idAvailable) {
                statement.setInt(index++, row.getInt("id"));
            }
            statement.setInt(index++, accountId);
            setNullableInt(statement, index++, categoryId);
            setNullableInt(statement, index++, projectId);
            setNullableInt(statement, index++, personId);
            statement.setString(index++, ledgerValues.transactionType());
            statement.setString(index++, ledgerValues.transactionPurpose());
            statement.setString(index++, ledgerValues.transactionStatus());
            statement.setDouble(index++, row.getDouble("amount"));
            statement.setString(index++, row.getString("transaction_date"));
            statement.setString(index++, safeText(row.getString("description"), ""));
            statement.setString(index++, safeText(row.getString("source"), "RECOVERED"));
            statement.setString(index++, cleanNullable(row.getString("payment_method")));
            statement.setString(index++, cleanNullable(row.getString("reference_number")));
            statement.setString(index, safeText(row.getString("created_at"), LocalDateTime.now().toString()));
            statement.executeUpdate();
        }
    }

    private boolean transactionIdExists(Connection connection, int id) throws SQLException {
        try (PreparedStatement statement = connection.prepareStatement("SELECT 1 FROM transactions WHERE id = ? LIMIT 1")) {
            statement.setInt(1, id);
            try (ResultSet resultSet = statement.executeQuery()) {
                return resultSet.next();
            }
        }
    }

    private String rowsText(ResultSet row, String columnName, String fallback) throws SQLException {
        String value = row.getString(columnName);
        return safeText(value, fallback);
    }

    private String sqliteForeignKeyCheck(Connection connection) throws SQLException {
        try (Statement statement = connection.createStatement();
             ResultSet resultSet = statement.executeQuery("PRAGMA foreign_key_check")) {
            List<String> failures = new ArrayList<>();
            while (resultSet.next()) {
                failures.add(resultSet.getString(1) + "#" + resultSet.getString(2));
                if (failures.size() >= 5) {
                    break;
                }
            }
            return String.join(", ", failures);
        }
    }

    public String validateDatabaseHealth() {
        try (Connection connection = connect()) {
            validateDatabaseHealth(connection);
            return "Database health check passed.";
        } catch (SQLException exception) {
            throw new IllegalStateException("Database health check failed", exception);
        }
    }

    private void validateDatabaseHealth(Connection connection) throws SQLException {
        String integrity = sqliteIntegrityCheck(connection);
        if (!"ok".equalsIgnoreCase(integrity)) {
            throw new SQLException("SQLite integrity check failed: " + integrity);
        }
        String foreignKeyCheck = sqliteForeignKeyCheck(connection);
        if (!foreignKeyCheck.isBlank()) {
            throw new SQLException("SQLite foreign key check failed: " + foreignKeyCheck);
        }

        requireTableColumns(connection, "accounts", List.of(
                "id",
                "account_name",
                "account_type",
                "currency",
                "bank_provider_name",
                "account_number",
                "opening_balance",
                "opening_balance_date",
                "minimum_balance",
                "account_purpose",
                "branch_name",
                "account_category",
                "account_subtype",
                "community_group_id",
                "is_system_account",
                "status",
                "notes",
                "created_at",
                "updated_at",
                "is_deleted"
        ));
        requireTableColumns(connection, "transactions", List.of(
                "id",
                "account_id",
                "transaction_type",
                "transaction_purpose",
                "transaction_status",
                "amount",
                "transaction_date",
                "source",
                "payment_method",
                "reference_number",
                "original_amount",
                "original_currency",
                "exchange_rate",
                "converted_amount",
                "converted_currency",
                "exchange_rate_source",
                "exchange_rate_timestamp",
                "is_deleted"
        ));
        requireTableColumns(connection, "exchange_rates", List.of(
                "id",
                "base_currency",
                "quote_currency",
                "rate",
                "rate_date",
                "rate_timestamp",
                "source",
                "rate_type",
                "provider_name",
                "is_manual",
                "is_active",
                "created_at",
                "updated_at"
        ));
        requireTableColumns(connection, "schema_version", List.of("version", "description", "applied_at"));
        requireTableColumns(connection, "schema_migration_history", List.of("migration_key", "version", "description", "applied_at"));
        requireTableColumns(connection, "system_event_log", List.of("id", "module_name", "action_name", "severity", "details", "created_at"));
        if (!viewExists(connection, "valid_transactions")) {
            throw new SQLException("Required view is missing: valid_transactions");
        }
        validateTransactionValidationTriggers(connection);
        requireReadableQuery(connection, """
                SELECT a.id, a.account_name, COALESCE(a.is_system_account, 0) AS is_system_account
                FROM accounts a
                WHERE COALESCE(a.is_deleted, 0) = 0
                LIMIT 1
                """, "accounts controller compatibility query");
        requireReadableQuery(connection, """
                SELECT id, account_id, transaction_type, transaction_purpose,
                       transaction_status, amount, transaction_date, is_deleted
                FROM valid_transactions
                LIMIT 1
                """, "valid transaction ledger compatibility query");
    }

    private void validateTransactionValidationTriggers(Connection connection) throws SQLException {
        List<String> incompatible = new ArrayList<>();
        boolean insertTriggerCompatible = false;
        boolean updateTriggerCompatible = false;
        for (TransactionTriggerMetadata trigger : listTransactionTriggers(connection)) {
            if (isObsoletePfmisTransactionValidationTrigger(trigger)) {
                incompatible.add(trigger.name());
            }
            if (TRANSACTION_VALIDATION_INSERT_TRIGGER.equals(trigger.name())
                    && isCompatibleTransactionValidationTriggerSql(trigger.sql())) {
                insertTriggerCompatible = true;
            }
            if (TRANSACTION_VALIDATION_UPDATE_TRIGGER.equals(trigger.name())
                    && isCompatibleTransactionValidationTriggerSql(trigger.sql())) {
                updateTriggerCompatible = true;
            }
        }
        if (!incompatible.isEmpty()) {
            throw new SQLException("Incompatible legacy transaction validation trigger(s) remain: "
                    + String.join(", ", incompatible)
                    + ". Run PFMIS database initialization to apply "
                    + TRANSACTION_LEDGER_VALIDATION_MIGRATION_KEY + ".");
        }
        if (!insertTriggerCompatible || !updateTriggerCompatible) {
            throw new SQLException("Canonical transaction validation triggers are missing or incompatible: "
                    + TRANSACTION_VALIDATION_INSERT_TRIGGER + ", " + TRANSACTION_VALIDATION_UPDATE_TRIGGER + ".");
        }
    }

    private String sqliteIntegrityCheck(Connection connection) throws SQLException {
        try (Statement statement = connection.createStatement();
             ResultSet resultSet = statement.executeQuery("PRAGMA integrity_check")) {
            return resultSet.next() ? safeText(resultSet.getString(1), "") : "";
        }
    }

    private void requireTableColumns(Connection connection, String tableName, List<String> requiredColumns) throws SQLException {
        if (!tableExists(connection, tableName)) {
            throw new SQLException("Required table is missing: " + tableName);
        }
        List<String> missing = new ArrayList<>();
        for (String column : requiredColumns) {
            if (!columnExists(connection, tableName, column)) {
                missing.add(column);
            }
        }
        if (!missing.isEmpty()) {
            throw new SQLException(tableName + " is missing required column(s): " + String.join(", ", missing));
        }
    }

    private boolean viewExists(Connection connection, String viewName) throws SQLException {
        try (PreparedStatement statement = connection.prepareStatement("""
                SELECT 1
                FROM sqlite_master
                WHERE type = 'view'
                  AND name = ?
                LIMIT 1
                """)) {
            statement.setString(1, viewName);
            try (ResultSet resultSet = statement.executeQuery()) {
                return resultSet.next();
            }
        }
    }

    private void requireReadableQuery(Connection connection, String sql, String description) throws SQLException {
        try (PreparedStatement statement = connection.prepareStatement(sql);
             ResultSet ignored = statement.executeQuery()) {
            // Preparing and executing the query verifies the schema contract used by functional controllers.
        } catch (SQLException exception) {
            throw new SQLException("Failed " + description + ": " + exception.getMessage(), exception);
        }
    }

    public List<BackupRecord> listBackupHistory() {
        List<BackupRecord> records = new ArrayList<>();
        List<String> knownFiles = new ArrayList<>();
        String sql = """
                SELECT backup_file, created_at, file_size, checksum, contents, status
                FROM backup_history
                ORDER BY created_at DESC
                """;
        try (Connection connection = connect()) {
            initializeBackupHistory(connection);
            try (PreparedStatement statement = connection.prepareStatement(sql);
                 ResultSet resultSet = statement.executeQuery()) {
            while (resultSet.next()) {
                String backupFile = resultSet.getString("backup_file");
                knownFiles.add(backupFile);
                records.add(new BackupRecord(
                        backupFile,
                        resultSet.getString("created_at"),
                        resultSet.getLong("file_size"),
                        resultSet.getString("checksum"),
                        resultSet.getString("contents"),
                        resultSet.getString("status")
                ));
            }
            }
        } catch (SQLException exception) {
            throw new IllegalStateException("Failed to load backup history", exception);
        }

        Path directory = defaultBackupDirectory();
        if (!Files.isDirectory(directory)) {
            return records;
        }
        try (var stream = Files.list(directory)) {
            stream.filter(path -> path.getFileName().toString().toLowerCase(Locale.ENGLISH).endsWith(".db"))
                    .sorted(Comparator.comparing(path -> path.getFileName().toString()))
                    .forEach(path -> addDiscoveredBackup(records, knownFiles, path));
        } catch (IOException exception) {
            throw new IllegalStateException("Failed to scan backup folder", exception);
        }
        return records;
    }

    private void addDiscoveredBackup(List<BackupRecord> records, List<String> knownFiles, Path backupFile) {
        Path normalized = backupFile.toAbsolutePath().normalize();
        if (knownFiles.contains(normalized.toString())) {
            return;
        }
        try {
            String checksum = Files.isRegularFile(checksumFile(normalized))
                    ? Files.readString(checksumFile(normalized)).trim()
                    : sha256(normalized);
            records.add(new BackupRecord(
                    normalized.toString(),
                    Files.getLastModifiedTime(normalized).toString(),
                    Files.size(normalized),
                    checksum,
                    "Discovered SQLite backup file",
                    "FOUND"
            ));
        } catch (IOException exception) {
            records.add(new BackupRecord(
                    normalized.toString(),
                    "",
                    0,
                    "",
                    "Discovered file could not be read",
                    "UNREADABLE"
            ));
        }
    }

    private void recordBackup(BackupRecord record) {
        String sql = """
                INSERT INTO backup_history (backup_file, checksum, file_size, contents, status, created_at)
                VALUES (?, ?, ?, ?, ?, ?)
                """;
        try (Connection connection = connect()) {
            initializeBackupHistory(connection);
            try (PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setString(1, record.getBackupFile());
            statement.setString(2, record.getChecksum());
            statement.setLong(3, record.getFileSize());
            statement.setString(4, record.getContents());
            statement.setString(5, record.getStatus());
            statement.setString(6, record.getCreatedAt());
            statement.executeUpdate();
            }
        } catch (SQLException exception) {
            throw new IllegalStateException("Failed to record backup history", exception);
        }
    }

    private String backupFileName(String requestedName) {
        String base = requestedName == null || requestedName.isBlank() ? "pfmis-backup" : requestedName.trim();
        base = base.replaceAll("[^A-Za-z0-9._-]+", "-").replaceAll("-+", "-");
        if (base.isBlank() || ".".equals(base) || "..".equals(base)) {
            base = "pfmis-backup";
        }
        if (base.toLowerCase(Locale.ENGLISH).endsWith(".db")) {
            base = base.substring(0, base.length() - 3);
        }
        return base + "-" + LocalDateTime.now().format(FILE_TIMESTAMP_FORMAT) + ".db";
    }

    private Path checksumFile(Path backupFile) {
        return backupFile.resolveSibling(backupFile.getFileName() + ".sha256");
    }

    private Path requireBackupFile(Path backupFile) {
        if (backupFile == null) {
            throw new IllegalArgumentException("Select a backup file first.");
        }
        Path normalized = backupFile.toAbsolutePath().normalize();
        if (!Files.isRegularFile(normalized)) {
            throw new IllegalArgumentException("Backup file does not exist: " + normalized);
        }
        return normalized;
    }

    private boolean tableExists(Connection connection, String tableName) throws SQLException {
        try (PreparedStatement statement = connection.prepareStatement("""
                SELECT 1
                FROM sqlite_master
                WHERE type = 'table'
                  AND name = ?
                LIMIT 1
                """)) {
            statement.setString(1, tableName);
            try (ResultSet resultSet = statement.executeQuery()) {
                return resultSet.next();
            }
        }
    }

    private boolean columnExists(Connection connection, String tableName, String columnName) throws SQLException {
        try (PreparedStatement statement = connection.prepareStatement("PRAGMA table_info(" + tableName + ")");
             ResultSet resultSet = statement.executeQuery()) {
            while (resultSet.next()) {
                if (columnName.equalsIgnoreCase(resultSet.getString("name"))) {
                    return true;
                }
            }
        }
        return false;
    }

    private String sha256(Path file) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            try (var input = Files.newInputStream(file)) {
                byte[] buffer = new byte[8192];
                int read;
                while ((read = input.read(buffer)) >= 0) {
                    if (read > 0) {
                        digest.update(buffer, 0, read);
                    }
                }
            }
            return HexFormat.of().formatHex(digest.digest());
        } catch (IOException | NoSuchAlgorithmException exception) {
            throw new IllegalStateException("Failed to calculate backup checksum", exception);
        }
    }

