    public TransferPostingResult recordTransferWithFee(
            int fromAccountId,
            int toAccountId,
            double amountSent,
            double amountReceived,
            double transferFee,
            Integer feeCategoryId,
            LocalDate date,
            String description,
            String paymentMethod,
            String referenceNumber,
            TransferFxMetadata fxMetadata
    ) {
        if (fromAccountId == toAccountId) {
            throw new IllegalArgumentException("Choose two different accounts for a transfer");
        }
        if (amountSent <= 0 || amountReceived <= 0) {
            throw new IllegalArgumentException("Transfer amounts must be greater than zero");
        }
        if (transferFee < 0) {
            throw new IllegalArgumentException("Transfer fee cannot be negative");
        }
        if (date == null) {
            throw new IllegalArgumentException("Transfer date is required");
        }

        Account fromSnapshot = accountSnapshot(fromAccountId);
        Account toSnapshot = accountSnapshot(toAccountId);
        requireActiveTransferAccount(fromSnapshot, "source");
        requireActiveTransferAccount(toSnapshot, "destination");
        double sourceDeduction = amountSent + transferFee;
        if (fromSnapshot.getCurrentBalance() + 0.005 < sourceDeduction) {
            throw new IllegalArgumentException("The source account does not have enough available funds to complete the transfer and fee.");
        }

        String transferReference = transferReference(referenceNumber);
        Integer resolvedFeeCategoryId = transferFee > 0
                ? (feeCategoryId == null ? Integer.valueOf(findOrCreateCategory("Transaction Fees", "EXPENSE").getId()) : feeCategoryId)
                : feeCategoryId;
        int outgoingId;
        int incomingId;
        Integer feeTransactionId = null;
        try (Connection connection = connect()) {
            connection.setAutoCommit(false);
            try {
                outgoingId = insertTransferRow(
                        connection,
                        fromAccountId,
                        null,
                        "TRANSFER_OUT",
                        amountSent,
                        date,
                        transferDescription("Transfer to " + toSnapshot.getAccountName(), description),
                        paymentMethod,
                        transferReference,
                        fxMetadata
                );
                incomingId = insertTransferRow(
                        connection,
                        toAccountId,
                        outgoingId,
                        "TRANSFER_IN",
                        amountReceived,
                        date,
                        transferDescription("Transfer from " + fromSnapshot.getAccountName(), description),
                        paymentMethod,
                        transferReference,
                        fxMetadata
                );
                try (PreparedStatement update = connection.prepareStatement(
                        "UPDATE transactions SET related_transaction_id = ? WHERE id = ?")) {
                    update.setInt(1, incomingId);
                    update.setInt(2, outgoingId);
                    update.executeUpdate();
                }
                if (transferFee > 0) {
                    feeTransactionId = insertTransferFeeRow(
                            connection,
                            fromAccountId,
                            resolvedFeeCategoryId,
                            outgoingId,
                            transferFee,
                            date,
                            "Transfer fee for " + transferReference,
                            paymentMethod,
                            transferReference
                    );
                }
                recordSystemLog(
                        connection,
                        "Transaction Ledger",
                        "Transfer Completed",
                        "INFO",
                        "Transfer " + transferReference + " completed from " + fromSnapshot.getAccountName()
                                + " to " + toSnapshot.getAccountName()
                                + ". Amount: " + amountSent
                                + "; Fee: " + transferFee
                                + "; Outgoing: " + outgoingId
                                + "; Incoming: " + incomingId
                                + (feeTransactionId == null ? "" : "; Fee transaction: " + feeTransactionId)
                );
                connection.commit();
            } catch (SQLException | RuntimeException exception) {
                connection.rollback();
                throw exception;
            } finally {
                connection.setAutoCommit(true);
            }
        } catch (SQLException exception) {
            throw new IllegalStateException("Failed to record transfer", exception);
        }
        Account updatedSource = accountSnapshot(fromAccountId);
        Account updatedDestination = accountSnapshot(toAccountId);
        return new TransferPostingResult(
                outgoingId,
                incomingId,
                feeTransactionId,
                transferReference,
                updatedSource.getCurrentBalance(),
                updatedDestination.getCurrentBalance()
        );
    }

    private int insertTransferRow(
            Connection connection,
            int accountId,
            Integer relatedTransactionId,
            String purpose,
            double amount,
            LocalDate date,
            String description,
            String paymentMethod,
            String referenceNumber
    ) throws SQLException {
        return insertTransferRow(connection, accountId, relatedTransactionId, purpose, amount, date, description, paymentMethod, referenceNumber, null);
    }

    private int insertTransferRow(
            Connection connection,
            int accountId,
            Integer relatedTransactionId,
            String purpose,
            double amount,
            LocalDate date,
            String description,
            String paymentMethod,
            String referenceNumber,
            TransferFxMetadata fxMetadata
    ) throws SQLException {
        String sql = """
                INSERT INTO transactions (
                    account_id, related_transaction_id, transaction_type, transaction_purpose,
                    transaction_status, amount, transaction_date, description, source, payment_method, reference_number,
                    original_amount, original_currency, exchange_rate, converted_amount, converted_currency,
                    exchange_rate_source, exchange_rate_timestamp, exchange_rate_provider, exchange_rate_type, exchange_rate_date
                ) VALUES (?, ?, 'TRANSFER', ?, 'COMPLETED', ?, ?, ?, 'TRANSFER', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """;
        try (PreparedStatement insert = connection.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
            insert.setInt(1, accountId);
            setNullableInt(insert, 2, relatedTransactionId);
            insert.setString(3, purpose);
            insert.setDouble(4, amount);
            insert.setString(5, date.toString());
            insert.setString(6, description);
            insert.setString(7, cleanNullable(paymentMethod));
            insert.setString(8, cleanNullable(referenceNumber));
            bindTransferFxMetadata(insert, 9, fxMetadata);
            insert.executeUpdate();
            try (ResultSet keys = insert.getGeneratedKeys()) {
                if (keys.next()) {
                    return keys.getInt(1);
                }
            }
        }
        throw new SQLException("Transfer row was saved without a generated id");
    }

    private void bindTransferFxMetadata(PreparedStatement statement, int startIndex, TransferFxMetadata metadata) throws SQLException {
        if (metadata == null) {
            for (int offset = 0; offset < 10; offset++) {
                statement.setNull(startIndex + offset, java.sql.Types.NULL);
            }
            return;
        }
        statement.setBigDecimal(startIndex, metadata.originalAmount());
        statement.setString(startIndex + 1, cleanNullable(metadata.originalCurrency()));
        statement.setBigDecimal(startIndex + 2, metadata.exchangeRate());
        statement.setBigDecimal(startIndex + 3, metadata.convertedAmount());
        statement.setString(startIndex + 4, cleanNullable(metadata.convertedCurrency()));
        statement.setString(startIndex + 5, cleanNullable(metadata.exchangeRateSource()));
        statement.setString(startIndex + 6, metadata.exchangeRateTimestamp() == null ? null : metadata.exchangeRateTimestamp().toString());
        statement.setString(startIndex + 7, cleanNullable(metadata.exchangeRateProvider()));
        statement.setString(startIndex + 8, cleanNullable(metadata.exchangeRateType()));
        statement.setString(startIndex + 9, metadata.exchangeRateDate() == null ? null : metadata.exchangeRateDate().toString());
    }

